def _handle_dict(target, spec, scope):
    if not isinstance(target, dict):
        raise MatchError("{0!r} is not a dict", target)

    ret = {}
    spec_keys = sorted(spec.keys(), key=_precedence)
    matched_spec_keys = set()

    for target_key, target_val in target.items():
        for spec_key in spec_keys:
            try:
                scope[glom](target_key, spec_key, scope)
            except GlomError:
                continue
            matched_spec_keys.add(spec_key)
            spec_val = spec[spec_key]
            ret[target_key] = scope[glom](target_val, spec_val, scope)
            break
        else:
            raise MatchError("key {0!r} didn't match any of {1!r}", target_key, 
                           [k.key if type(k) in (Required, Optional) else k for k in spec_keys])

    for spec_key in spec_keys:
        if spec_key not in matched_spec_keys:
            if type(spec_key) is Required:
                raise MatchError("target missing expected keys {0!r}", spec_key.key)

    return ret
```

